  const la = a.toLowerCase();
  const lb = b.toLowerCase();
  if (la !== lb) return la < lb ? -1 : 1;
  return a < b ? -1 : a > b ? 1 : 0;
}

function missing(v) {
  return v === undefined || v === null;
}

function compareValues(a, b) {
  if (typeof a === 'string' && typeof b === 'string') return nameCompare(a, b);
  return a < b ? -1 : a > b ? 1 : 0;
}

